package net.civeira.phylax.feature.observe.observedsource.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSourceKindOptions;

class KindVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property kind of observed source ")
  void test_kind_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> KindVO.tryFrom("_BACKEND_"));
    Assertions.assertEquals(ObservedSourceKindOptions.BACKEND,
        KindVO.tryFrom("BACKEND").getKind().orElse(null));
    Assertions.assertFalse(KindVO.nullValue().getKind().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(KindVO.tryFrom(null).getKind().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(ObservedSourceKindOptions.BACKEND,
        KindVO.from(ObservedSourceKindOptions.BACKEND).getKind().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> KindVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + ObservedSourceKindOptions.BACKEND + "]",
        KindVO.from(ObservedSourceKindOptions.BACKEND).toString());
  }
}
